// TypeScript port of ~/josh-workspace/skills/acord-forms/scripts/map_acord131.py build(), limited to the keys this site posts.
// Output = { PDF field name -> text } exactly as the real mapper writes it. scripts/compare131.mjs diffs this against the real mapper.
// Cell names for position-resolved cells come from src/data/acord131-map.json (generated by the mapper's own at()).
export type Names = { single: Record<string, string>; q2: Record<string, string>; k20: string; tailYes: string; tailNo: string }

const yn = (v: string): boolean | null => { const m = /^(yes|y|no|n)\b/.exec((v || '').trim().toLowerCase()); return m ? m[1].startsWith('y') : null }
const term = (s: string): [string | null, string | null] => { const m = /^\s*(\S+)\s+to\s+(\S+)\s*$/.exec(s || ''); return m ? [m[1], m[2]] : [null, null] }
const carrier = (v: string | undefined) => (v ? v.split(' / ')[0].trim() : v)

export function mapPayload131(d: Record<string, string>, N: Names): Record<string, string> {
  const T: Record<string, string> = {}
  const put = (f: string, v: string | null | undefined) => { if (v !== null && v !== undefined && String(v).trim() !== '') T[f] = String(v) }
  for (const [k, f] of Object.entries(N.single)) if (k in d) put(f, d[k])
  if (d['legal entity name']) put('EFFECTIVE DATE', d['legal entity name'] + (d['business address'] ? ', ' + d['business address'] : ''))
  const sub = d['names and locations of any subsidiary companies'] || ''
  const ops = [d['description of operations'], sub.trim().toLowerCase().startsWith('none') ? '' : sub].filter(Boolean).join(' - ')
  if (ops) { put('NAME AND LOCATION OF PRIMARY AND ALL SUBSIDIARY COMPANIES Describe OperationsRow1', ops); put('Row1', '1') }
  const b = (d['billing preference'] || '').toLowerCase()
  if (b) { if (b.includes('agency')) put('EXPIRATION DATE_2', 'X'); else if (b.includes('direct')) put('EXPIRATION DATE', 'X') }
  if ('do you want first dollar defense' in d) { const y = yn(d['do you want first dollar defense']); if (y !== null) put(y ? 'FIRST DOLLAR DEFENSE_2' : 'YES', 'X') }
  for (const [lab, fcar, feff, fexp] of [
    ['underlying auto', 'CARRIERPOLICY NUMBERAUTOMOBILE LIABILITY', 'POLICY EFF DATEAUTOMOBILE LIABILITY', 'POLICY EXP DATEAUTOMOBILE LIABILITY'],
    ['underlying employers liability', 'CARRIERPOLICY NUMBEREMPLOYERS LIABILITY', 'POLICY EFF DATEEMPLOYERS LIABILITY', 'POLICY EXP DATEEMPLOYERS LIABILITY']]) {
    put(fcar, carrier(d[lab + ' carrier and policy number']))
    const [e, x] = term(d[lab + ' policy term']); put(feff, e); put(fexp, x)
  }
  const gl = [carrier(d['underlying general liability carrier and policy number']), d['underlying general liability policy term'], d['is the underlying GL occurrence or claims made']]
  put('CARRIERPOLICY NUMBERGENERAL LIABILITY POLICY TYPE OCCUR CLAIMS MADE', gl.filter(Boolean).join('\n'))
  const dc = (d['are defense costs within the aggregate, a separate limit, or unlimited'] || '').toLowerCase()
  if (dc) {
    const f = dc.includes('within') ? 'INDICATE THE EDITION DATE OF THE ISO SIMPLIFIED FORM OR SIMILAR FILING FOR THE UNDERLYING COVERAGE'
      : dc.includes('separate') ? 'WITHIN AGGREGATE LIMITS_2' : dc.includes('unlimited') ? 'A SEPARATE LIMIT' : null
    if (f) put(f, 'X')
  }
  const k3 = 'has any product, work, accident or location been excluded, uninsured or self-insured under previous coverage'
  if (k3 in d) { const y = yn(d[k3]); if (y !== null) put(y ? 'HAS ANY PRODUCT WORK ACCIDENT OR LOCATION BEEN EXCLUDED UNINSURED OR SELF INSURED FROM ANY PREVIOUS COVERAGE' : 'YES_2', 'X') }
  const k6 = 'was tail coverage purchased for any previous primary or excess policy'
  if (k6 in d) { const y = yn(d[k6]); if (y !== null) put(y ? N.tailYes : N.tailNo, 'X') }
  for (const [lab, f] of Object.entries(N.q2)) if (lab in d) { const y = yn(d[lab]); if (y !== null) put(f, y ? 'Y ' : ' N') }
  const k20 = 'do your products contain hazardous materials needing special disposal'
  if (k20 in d) { const y = yn(d[k20]); if (y !== null) put(N.k20, y ? 'Y' : 'N') }
  const claims = (d['liability claims over $10,000 in the past 5 years'] || '').trim()
  const plr = d['describe the product liability loss']
  const rem: string[] = []
  if (['none', 'no', ''].includes(claims.toLowerCase())) { if (claims) put('ACORD 131 200201', 'X') } else rem.push(claims)
  if (plr && !claims.includes(plr)) rem.push(plr)
  if (rem.length) put('REMARKS', rem.join('\n'))
  return T
}
